'use strict';

// MODULES //

var tape = require( 'tape' );
var PI = require( '@stdlib/constants/float32/pi' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var roundsdf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof roundsdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v;

	v = roundsdf( NaN, 2, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, NaN, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, 2, NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( NaN, NaN, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( NaN, NaN, NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `n = +-infinity`', function test( t ) {
	var v;

	v = roundsdf( PI, PINF, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, NINF, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `n < 1`', function test( t ) {
	var v;

	v = roundsdf( PI, 0, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, -1, 10 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `b = +-infinity`', function test( t ) {
	var v;

	v = roundsdf( PI, 2, PINF );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, 2, NINF );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaN` if provided `b <= 0`', function test( t ) {
	var v;

	v = roundsdf( PI, 2, 0 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	v = roundsdf( PI, 2, -1 );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var v = roundsdf( PINF, 5, 10 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var v = roundsdf( NINF, 3, 10 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v;

	v = roundsdf( -0.0, 1, 10 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	v = roundsdf( -0.0, 2, 10 );
	t.strictEqual( isNegativeZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v;

	v = roundsdf( 0.0, 1, 10 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	v = roundsdf( +0.0, 2, 10 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures (base 10)', function test( t ) {
	// Tested against Julia...
	t.strictEqual( roundsdf( PI, 1, 10 ), 3.0, 'returns expected value' );
	t.strictEqual( roundsdf( -PI, 1, 10 ), -3.0, 'returns expected value' );
	t.strictEqual( roundsdf( PI, 2, 10 ), 3.0999999046325684, 'returns expected value' );
	t.strictEqual( roundsdf( -PI, 2, 10 ), -3.0999999046325684, 'returns expected value' );
	t.strictEqual( roundsdf( PI, 3, 10 ), 3.140000104904175, 'returns expected value' );
	t.strictEqual( roundsdf( -PI, 3, 10 ), -3.140000104904175, 'returns expected value' );
	t.strictEqual( roundsdf( PI, 4, 10 ), 3.1419999599456787, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 1, 10 ), 10000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 2, 10 ), 12000.0, 'returns expected value' );
	t.strictEqual( roundsdf( -12368.0, 2, 10 ), -12000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 12368.0, 3, 10 ), 12400.0, 'returns expected value' );
	t.strictEqual( roundsdf( -12368.0, 3, 10 ), -12400.0, 'returns expected value' );
	t.strictEqual( roundsdf( 999999.0, 3, 10 ), 1000000.0, 'returns expected value' );
	t.strictEqual( roundsdf( 0.5, 1, 10 ), 0.5, 'returns expected value' );
	t.strictEqual( roundsdf( 96.0, 1, 10 ), 100.0, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures (base 2)', function test( t ) {
	// Tested against Julia...
	t.strictEqual( roundsdf( 0.0313, 1, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 2, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 5, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 9, 2 ), 0.03125, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 10, 2 ), 0.03131103515625, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 11, 2 ), 0.03131103515625, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 12, 2 ), 0.0312957763671875, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 13, 2 ), 0.03130340576171875, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 14, 2 ), 0.031299591064453125, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding a numeric value with a specified number of significant figures using an arbitrary base', function test( t ) {
	// Tested against Julia...
	t.strictEqual( roundsdf( 0.0313, 1, 16 ), 0.03125, 'returns expected value' );
	t.strictEqual( roundsdf( 0.0313, 5, 16 ), 0.03130000829696655, 'returns expected value' );
	t.strictEqual( roundsdf( 255.0, 1, 16 ), 256.0, 'returns expected value' );
	t.strictEqual( roundsdf( 255.0, 2, 16 ), 255.0, 'returns expected value' );
	t.end();
});

tape( 'if the function encounters overflow, the function returns the input value', function test( t ) {
	var x;
	var v;

	x = 3.1468234062194824;
	v = roundsdf( x, 1000, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = -3.1468234062194824;
	v = roundsdf( x, 1000, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = 16777216.0;
	v = roundsdf( x, 320, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = -16777216.0;
	v = roundsdf( x, 320, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	// Subnormal values for which the required scale factor overflows:
	x = f32( 1.0e-42 );
	v = roundsdf( x, 2, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	x = f32( 1.0e-40 );
	v = roundsdf( x, 2, 2 );
	t.strictEqual( v, x, 'returns expected value' );

	x = f32( 1.401298464324817e-45 );
	v = roundsdf( x, 1, 10 );
	t.strictEqual( v, x, 'returns expected value' );

	t.end();
});
